import{_ as a,o as i,c as s,a8 as o}from"./chunks/framework.R_sesYpn.js";const u=JSON.parse('{"title":"BlackLab Server","description":"","frontmatter":{"order":-1},"headers":[],"relativePath":"server/index.md","filePath":"server/index.md","lastUpdated":1786522245000}'),t={name:"server/index.md"};function r(n,e,l,c,d,h){return i(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="blacklab-server" tabindex="-1">BlackLab Server <a class="header-anchor" href="#blacklab-server" aria-label="Permalink to &quot;BlackLab Server&quot;">​</a></h1> <p>BlackLab Server is the REST API (web service) for accessing BlackLab corpora. For most users, it is the best way to use BlackLab. It can be used from any programming language, and for anything from quick analysis scripts to full-featured corpus search applications (such as <a href="https://blacklab-frontend.ivdnt.org/" target="_blank" rel="noreferrer">BlackLab Frontend</a>).</p> <p>See <a href="/guide/getting-started.html">Getting started</a> for the basics. Below, we&#39;ll assume you have BlackLab Server up and running.</p> <p>What you might want to look at next:</p> <ul><li>Learn the <a href="./rest-api/by-example.html">API by example</a></li> <li>Consult the <a href="/server/rest-api/">API reference</a></li> <li>Use BlackLab from <a href="./from-different-languages.html">different programming languages</a></li> <li>Configure BlackLab through <a href="./configuration.html">blacklab-server.yaml</a>.</li></ul> <p>Below we&#39;ll look at a few specific subjects.</p> <h2 id="configuration-directory" tabindex="-1">Configuration directory <a class="header-anchor" href="#configuration-directory" aria-label="Permalink to &quot;Configuration directory&quot;">​</a></h2> <p>BlackLab&#39;s configuration directory contains its <code>blacklab-server.yaml</code> as well as other files (mentioned below).</p> <p>For Docker users, this directory is always <code>/etc/blacklab</code>. If you don&#39;t use Docker, and want to use a different configuration directory, here&#39;s where BlackLab will look:</p> <ul><li>the directory specified in <code>$BLACKLAB_CONFIG_DIR</code></li> <li><code>$HOME/.blacklab/</code> (if you&#39;re running Tomcat under your own user account, e.g. on a development machine; <code>$HOME</code> refers to your home directory)</li></ul> <details class="details custom-block"><summary>Passing <code>$BLACKLAB_CONFIG_DIR</code> to Tomcat</summary> <p>To pass <code>$BLACKLAB_CONFIG_DIR</code> to Tomcat, create or edit <code>setenv.sh</code> in the Tomcat <code>bin</code> directory to set environment variables. You can also set them in <code>/etc/sysconfig/tomcat</code> if using systemd. Check the Tomcat documentation for details</p></details> <p>There can be various subdirectories in the configuration directory:</p> <ul><li><code>formats/</code> (<code>.blf.yaml</code> input format configuration files)</li> <li><code>plugins/</code> (<a href="/development/customization/">plugins</a> with their configuration and any files they might need) should be if they exist</li></ul> <p><a href="https://blacklab-frontend.ivdnt.org/" target="_blank" rel="noreferrer">BlackLab Frontend</a> will look for its main configuration file and per-corpus configuration files (<code>projectconfigs</code>) here.</p> <h2 id="memory-usage" tabindex="-1">Memory usage <a class="header-anchor" href="#memory-usage" aria-label="Permalink to &quot;Memory usage&quot;">​</a></h2> <p>If your memory settings are suboptimal, performance may suffer.</p> <p>This is assuming your machine has enough memory for what you&#39;re trying to do, of course. As a rough indication: we run a 4.5 billion token corpus on a (virtual) machine with 50 GB of memory, with few simultaneous users that generally perform simple queries, with the occasional heavier query.</p> <h3 id="heap-memory-vs-disk-cache" tabindex="-1">Heap memory vs. disk cache <a class="header-anchor" href="#heap-memory-vs-disk-cache" aria-label="Permalink to &quot;Heap memory vs. disk cache&quot;">​</a></h3> <p>For larger corpora, it is important to give Tomcat&#39;s JVM enough (heap) memory. (if memory is low and/or fragmented, the JVM garbage collector might start taking 100% CPU moving objects in order to recover enough free space, slowing things down to a crawl)</p> <p>On the other hand, do not assign all of the system&#39;s memory to JVM&#39;s heap, either. You should leave a significant amount for the operating system&#39;s disk cache, which can greatly speed up certain operations.</p> <p>The optimum way to divide up memory depends on many factors, but a good starting point is to assign no more than 50% of the system memory to the JVM. You can then experiment with increasing or decreasing the heap size to see what works best in your case.</p> <p><strong>NOTE:</strong> If you are indexing unique ids for each word, you may also be able to save memory by <a href="/guide/index-your-data/annotations.html#disable-the-forward-index">disabling the forward index</a> for that &#39;unique id&#39; annotation.</p> <h3 id="how-do-i-configure-heap-memory" tabindex="-1">How do I configure heap memory? <a class="header-anchor" href="#how-do-i-configure-heap-memory" aria-label="Permalink to &quot;How do I configure heap memory?&quot;">​</a></h3> <p>For Docker users, this is done by setting the <code>JAVA_OPTS</code> environment variable, e.g. in your <code>docker-compose.yml</code>:</p> <div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  blacklab</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">instituutnederlandsetaal/blacklab:dev</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Set the JVM&#39;s maximum heap size to 10 GB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;JAVA_OPTS=-Xmx10G&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # (... volumes, etc.)</span></span></code></pre></div><p>For non-Docker usage, it&#39;s similar; for example, see <a href="http://crunchify.com/how-to-change-jvm-heap-setting-xms-xmx-of-tomcat/" target="_blank" rel="noreferrer">here</a>.</p> <h2 id="docker-images" tabindex="-1">Docker images <a class="header-anchor" href="#docker-images" aria-label="Permalink to &quot;Docker images&quot;">​</a></h2> <p>Docker images are available on <a href="https://hub.docker.com/orgs/instituutnederlandsetaal/repositories?search=blacklab" target="_blank" rel="noreferrer">Docker Hub</a>.</p> <p>These are the two blacklab Docker images available:</p> <ul><li><code>blacklab</code> is the base image, with BlackLab running inside Tomcat</li> <li><code>blacklab-frontend</code> adds BlackLab Frontend as well</li></ul> <p>The are numbered release tags such as <code>4.1.1</code>, <code>4.1</code> and <code>4</code>. For the most stable experience, use a numbered release, especially a specific patch version. (<code>4</code> is always the latest minor/patch, <code>4.1</code> the latest patch)</p> <p>There is also a <code>dev</code> tag that is always up to date with the <code>dev</code> branch. This provides more features and often better performance, but obviously less stability. We do aim to always keep the <code>dev</code> version in a releasable state, though.</p> <p>If you want to build your own image from source, use a recent Docker version (at least version 23).</p> <h3 id="paths-in-the-images" tabindex="-1">Paths in the images <a class="header-anchor" href="#paths-in-the-images" aria-label="Permalink to &quot;Paths in the images&quot;">​</a></h3> <p>The images use the following paths:</p> <ul><li><code>/etc/blacklab</code>: BlackLab&#39;s configuration directory. This is where main configuration file <code>blacklab-server.yaml</code> goes, plus the <code>formats</code> and <code>plugins</code> directories.</li> <li><code>/data/index</code>: where BlackLab looks for indexed corpora.</li> <li><code>/data/user-index</code>: where private user corpora are stored (only available if authentication is enabled)</li></ul> <p>To extend the image&#39;s built-in <code>blacklab-server.yaml</code> file, bind mount a file at <code>/etc/blacklab/blacklab-server.override.yaml</code> (dev/future v5) and it will be read after <code>blacklab-server.yaml</code>. So in <code>docker-compose.yml</code>:</p> <div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    volumes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # BlackLab will look for corpora here </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/data/blacklab-corpora:/data/index</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Some configuration overrides</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./my-bls-settings.yaml:/etc/blacklab/blacklab-server.override.yaml</span></span></code></pre></div><h3 id="build-your-own-image" tabindex="-1">Build your own image <a class="header-anchor" href="#build-your-own-image" aria-label="Permalink to &quot;Build your own image&quot;">​</a></h3> <p>To build the Docker image yourself, run this from the <code>docker</code> subdirectory:</p> <div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div>`,79)])])}const m=a(t,[["render",r]]);export{u as __pageData,m as default};
